INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Läuft ein Typ-1-Hypervisor immer direkt auf der Hardware?', 2, '[{"text": "Ja", "correct": true, "because": "Keine Zwischenschicht nötig"}, {"text": "Nein", "correct": false, "because": "Typ 1 ist bare-metal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Hypervisor wähle ich für maximale Performance?', 3, '[{"text": "Typ 1", "correct": true, "because": "Direkte Hardwarezugriffe"}, {"text": "Typ 2", "correct": false, "because": "Läuft über Host-BS"}, {"text": "Keinen", "correct": false, "because": "Hypervisor nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Typ-2-Hypervisor für Tests geeignet?', 5, '[{"text": "Einfache Installation", "correct": true, "because": "Läuft auf bestehendem BS"}, {"text": "Flexibilität", "correct": true, "because": "Keine dedizierte Hardware nötig"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Weniger isoliert"}, {"text": "Maximale Effizienz", "correct": false, "because": "Overhead durch Host"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Typ 1 ist effizienter als Typ 2. b) Typ 2 braucht kein Host-BS.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Host-BS erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Typ-1-Hypervisors für Server?', 4, '[{"text": "Hardwarekompatibilität", "correct": false, "because": "Muss passen"}, {"text": "Performance", "correct": false, "because": "Kern der Entscheidung"}, {"text": "Gaming-Funktionen", "correct": true, "because": "Irrelevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Typ-2-Hypervisors für Produktion geeignet sind?', 2, '[{"text": "Nein", "correct": true, "because": "Weniger effizient und sicher"}, {"text": "Ja", "correct": false, "because": "Eher für Testumgebungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature priorisiere ich für einen Typ-1-Hypervisor?', 3, '[{"text": "Direkte Hardwaresteuerung", "correct": true, "because": "Maximale Leistung"}, {"text": "Einfache Bedienung", "correct": false, "because": "Sekundär"}, {"text": "Host-BS-Kompatibilität", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Typ-1-Hypervisor?', 5, '[{"text": "Hohe Effizienz", "correct": true, "because": "Kein Host-BS-Overhead"}, {"text": "Bessere Isolation", "correct": true, "because": "Direkte VM-Steuerung"}, {"text": "Geringere Kosten", "correct": false, "because": "Setup kann teuer sein"}, {"text": "Einfache Installation", "correct": false, "because": "Komplexer als Typ 2"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Typ 2 ist einfacher zu installieren. b) Typ 1 ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch für klein geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Typ-2-Hypervisor?', 4, '[{"text": "Host-Betriebssystem", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Kompatible Hardware", "correct": false, "because": "Muss unterstützt werden"}, {"text": "Dedizierte Server", "correct": true, "because": "Läuft auf bestehender Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Typ-1-Hypervisor sicherer als Typ 2?', 2, '[{"text": "Ja", "correct": true, "because": "Direkte Kontrolle, weniger Angriffsfläche"}, {"text": "Nein", "correct": false, "because": "Typ 2 hat Host-BS-Risiken"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Typ-1-Hypervisor in einem Rechenzentrum wichtig?', 4, '[{"text": "Skalierbarkeit", "correct": true, "because": "Viele VMs möglich"}, {"text": "Hohe Leistung", "correct": true, "because": "Direkte Hardwarezugriffe"}, {"text": "Einfache GUI", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Typ-2-Hypervisors keine VMs isolieren. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Isolation möglich, aber weniger stark"}, {"text": "Ja", "correct": false, "because": "Isolation vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich für einen Typ-2-Hypervisor auf einem Laptop?', 3, '[{"text": "Einfache Nutzung", "correct": true, "because": "Für Testzwecke ideal"}, {"text": "Maximale Performance", "correct": false, "because": "Typ 1 besser"}, {"text": "Hohe Sicherheit", "correct": false, "because": "Sekundär bei Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Typ 1 ist bare-metal. b) Typ 2 ist effizienter als Typ 1.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Typ 1 ist effizienter"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein Typ-2-Hypervisor?', 5, '[{"text": "Overhead durch Host-BS", "correct": true, "because": "Zusätzliche Schicht"}, {"text": "Geringere Isolation", "correct": true, "because": "Abhängig vom Host"}, {"text": "Hohe Kosten", "correct": false, "because": "Oft günstiger"}, {"text": "Schwere Verwaltung", "correct": false, "because": "Eher einfacher"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Typ-1-Hypervisor für kleine Netzwerke unwichtig?', 3, '[{"text": "Hardwareunterstützung", "correct": false, "because": "Muss kompatibel sein"}, {"text": "Effizienz", "correct": false, "because": "Wichtig für Leistung"}, {"text": "Massive Clustering", "correct": true, "because": "Übertrieben für klein"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein Typ-2-Hypervisor mehr Ressourcen?', 3, '[{"text": "Ja", "correct": true, "because": "Host-BS benötigt zusätzliche Ressourcen"}, {"text": "Nein", "correct": false, "because": "Typ 1 effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Typ-1-Hypervisors für Desktops gedacht sind?', 2, '[{"text": "Nein", "correct": true, "because": "Eher für Server"}, {"text": "Ja", "correct": false, "because": "Typ 2 für Desktops üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Hypervisor wähle ich für ein großes Unternehmen?', 4, '[{"text": "Typ 1", "correct": true, "because": "Hohe Leistung und Skalierbarkeit"}, {"text": "Typ 2", "correct": false, "because": "Weniger geeignet für Produktion"}, {"text": "Keinen", "correct": false, "because": "Virtualisierung nötig"}]');
